INSERT INTO pregunta (id, cuestionario_id, codigo, texto, tipo, opciones, dimension_id, version, orden, respuesta_critica) VALUES ('2f2d27cb-3372-4dfd-975d-adf890c54920', 'c1111111-1111-1111-1111-111111111111', 'DOU_01', 'Si solo pudieras duplicar una línea de negocio durante los próximos 12 meses, ¿cuál elegirías y por qué?', 'CORTA', '[]'::jsonb, 'negocio_crecimiento', 1, 1, NULL) ON CONFLICT (id) DO UPDATE SET texto = EXCLUDED.texto, tipo = EXCLUDED.tipo, opciones = EXCLUDED.opciones, dimension_id = EXCLUDED.dimension_id, orden = EXCLUDED.orden;
INSERT INTO pregunta (id, cuestionario_id, codigo, texto, tipo, opciones, dimension_id, version, orden, respuesta_critica) VALUES ('b8000000-0000-0000-0000-000000000001', 'c8888888-8888-8888-8888-888888888888', 'ESP_01', '¿Qué formación estás cursando actualmente y en qué período te encuentras?', 'FORMACION_PERIODO', '{"periodos":["Mes 1 – 3 (Conociendo tu Cámara / Fundamentos)","Mes 4 – 6 (Composición Visual)","Mes 7 – 9 (Iluminación Artificial / Estudio)","Mes 10 – 12 (Fotocreativa, Portafolio o Comercial)","Finalizado / Egresado(a)"],"formaciones":["Programa Integral de Fotografía (1 año)","Video Desde Cero (3 meses)","Workshop Adobe Lightroom","Creación de Contenido con Celular para Emprendedores","Masterclass Newborn","Cierres Efectivos para Fotógrafos Escolares","Otro taller o curso"]}'::jsonb, 'espacios_perfil', 5, 1, NULL) ON CONFLICT (id) DO UPDATE SET texto = EXCLUDED.texto, tipo = EXCLUDED.tipo, opciones = EXCLUDED.opciones, dimension_id = EXCLUDED.dimension_id, orden = EXCLUDED.orden;
INSERT INTO pregunta (id, cuestionario_id, codigo, texto, tipo, opciones, dimension_id, version, orden, respuesta_critica) VALUES ('b8000000-0000-0000-0000-000000000002', 'c8888888-8888-8888-8888-888888888888', 'ESP_02', 'En general, ¿qué tan feliz y satisfecho/a estás con tu experiencia en Escuela RunaFoto?', 'OPCION_MULTIPLE', '["⭐⭐⭐⭐⭐ ¡Me encanta! Excelente experiencia de aprendizaje","⭐⭐⭐⭐ Muy buena, estoy aprendiendo un montón","⭐⭐⭐ Regular, está bien pero puede mejorar","⭐⭐ Poco satisfecho/a, esperaba algo diferente","⭐ Muy insatisfecho/a"]'::jsonb, 'espacios_satisfaccion', 5, 2, NULL) ON CONFLICT (id) DO UPDATE SET texto = EXCLUDED.texto, tipo = EXCLUDED.tipo, opciones = EXCLUDED.opciones, dimension_id = EXCLUDED.dimension_id, orden = EXCLUDED.orden;
INSERT INTO pregunta (id, cuestionario_id, codigo, texto, tipo, opciones, dimension_id, version, orden, respuesta_critica) VALUES ('6dcd8a89-df49-4575-9715-c9a3aff0dd83', 'c1111111-1111-1111-1111-111111111111', 'DOU_02', '¿Qué parte de tu forma de vender consideras que marca la mayor diferencia frente a la competencia, y por qué crees que funciona?', 'CORTA', '[]'::jsonb, 'comercial', 1, 2, NULL) ON CONFLICT (id) DO UPDATE SET texto = EXCLUDED.texto, tipo = EXCLUDED.tipo, opciones = EXCLUDED.opciones, dimension_id = EXCLUDED.dimension_id, orden = EXCLUDED.orden;
