INSERT INTO pregunta (id, cuestionario_id, codigo, texto, tipo, opciones, dimension_id, version, orden, respuesta_critica) VALUES ('b8000000-0000-0000-0000-000000000006', 'c8888888-8888-8888-8888-888888888888', 'ESP_06', '¿Cuál de los nuevos ambientes te genera mayor emoción o ganas de usar en tus prácticas?', 'OPCION_MULTIPLE', '["💡 Estudio profesional de iluminación, fondos y esquemas de luz","🏛️ Museo de la Fotografía (con más de 60 cámaras históricas)","🎞️ Laboratorio de fotografía analógica Blanco y Negro","💻 Aulas tecnológicas equipadas para clases y edición digital","🚁 Almacén tecnológico (drones, VR, cámaras, luces y audio)","💄 Área de maquillaje y producción visual"]'::jsonb, 'espacios_conocimiento', 5, 6, NULL) ON CONFLICT (id) DO UPDATE SET texto = EXCLUDED.texto, tipo = EXCLUDED.tipo, opciones = EXCLUDED.opciones, dimension_id = EXCLUDED.dimension_id, orden = EXCLUDED.orden;
