INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('20343777-3a87-45f5-9c75-c7e64d37b56c', 'a0000000-0000-0000-0000-000000000005', '1d159bb1-792b-4ab3-b5c5-77703efa6fcd', '{"esTest":false,"deviceId":"xvyxdqz5ked","sesionId":"ns5ahsj2ahj","respuesta":"Depende si estamos en una FERIA NUPCIAL presencial intervengo en todo el proceso de venta. \n\ny Si el contacto es virtual,  sería en coordinación, seguimiento, contrato y cobranza.\n\nEn resumen, conozco y a veces participo en todo el proceso.","fingerprint":"6afbc1ac"}'::jsonb, '2026-07-08T17:58:36.558Z', '2026-07-09T15:31:21.487Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('3943fa13-0c32-49e4-9a7e-1503efa80e8e', 'a0000000-0000-0000-0000-000000000006', 'a4a6ee0e-8d25-4247-810b-f2fdd1526ab3', '{"esTest":false,"deviceId":"ccram7nkrbw","sesionId":"jxxpguovh2e","respuesta":"El iPhone 13 es el que más se utiliza para grabar y editar pero no tiene mucho espacio y ya no tiene WhatsApp, lo que dificulta poder pasarnos los archivos o fotos, el iPhone 11 tiene WhatsApp pero está teniendo problemas con su cámara porque la imagen se ve temblorosa y tampoco cuenta con espacio, los micrófonos para grabar también se pueden utilizar sin problema.","fingerprint":"27ea4b90"}'::jsonb, '2026-07-09T15:26:15.482Z', '2026-07-09T16:49:42.036Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
