INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('6a9e92ce-36b5-4112-88bd-9f9de2d0c696', 'a0000000-0000-0000-0000-000000000005', '91f2352c-0816-4d85-b9c2-8f14fd672ca9', '{"esTest":false,"deviceId":"xvyxdqz5ked","sesionId":"ns5ahsj2ahj","respuesta":"A nivel interno dentro de Runafoto, sugeriría que se debería mejorar el clima laboral haber empatía, valorar el trabajo de todos, y respetar a cada colaborador, me preocupa que haya mucha rotación en Runafoto desde que estoy ya más de un año he visto pasar y entrar a más de 12 colaboradores, algunos duran una semana, un mes y se van, también vi partir antiguos, allí hay un tema a evaluar, a nivel de realizadores no hay mucha estabilidad hay ligera rotación de personal y alguno que he escuchado de la propia boda de excolaboradores es que sienten que muchas veces no valoran a la gente y que tienen que rogar para sus compensaciones o sea me han dicho literal que piden apoyo y ellos apoyan en horas extras, en feriados, etc. Pero cuando piden compensar no les dan la facilidad. Ese sería mi feedback. Gracias.","fingerprint":"6afbc1ac"}'::jsonb, '2026-07-08T18:20:22.276Z', '2026-07-09T15:31:21.487Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('74ba9d8a-1093-44fc-ab0a-d66e659c2f9e', 'a0000000-0000-0000-0000-000000000005', '6c8c10c6-c59c-4e8a-b8c7-4151a76302f8', '{"esTest":false,"deviceId":"xvyxdqz5ked","sesionId":"ns5ahsj2ahj","respuesta":"Probablemente sea la atención presencial a los clientes que van a oficina de Trujillo a firmar contratos, no obstante, en la mayoría de casos los clientes hacen transacciones comerciales con nosotros vía llamada, whatsapp o reuniones virtuales, porque de allí las demás coordinaciones como validación de agenda, monitoreo de coberturas, atención a clientes corporativos o personas naturales la hacemos por llamada, whatsapp o virtualmente. Y en relación a los eventos presenciales en Lima, mi persona las toma, no con tanta frecuencia como las hay en Trujillo, quizá sea ello la única diferencia, porque de allí en relación a las actividades de gestión, coordinación, administrativa y comerciales son muy similares. Ya que la mayoría de estás actividades se gestionan a través de llamadas o reuniones virtuales.","fingerprint":"6afbc1ac"}'::jsonb, '2026-07-08T17:49:29.552Z', '2026-07-09T15:31:21.487Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
