INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('123aa1e7-6a94-46e3-a891-88448c9a1a56', 'a0000000-0000-0000-0000-000000000003', '43e5d9d0-9577-4faa-8c1b-46b720a130d7', '{"esTest":false,"deviceId":"7wm29mpg7nm","sesionId":"84wetxupq9","respuesta":"toda la informacion basica del modulo 1: conociendo tu camara.\ny las actualizaciones de flyers de los grupos que se van aperturando. ","fingerprint":"a75fefd7"}'::jsonb, '2026-07-09T16:10:39.856Z', '2026-07-09T16:22:32.312Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('bb2e6b87-fdc0-45ab-a78e-8077dd4d2c8b', 'a0000000-0000-0000-0000-000000000005', 'f1a59588-b2e8-4b13-87bb-9c3b3f751399', '{"esTest":false,"deviceId":"xvyxdqz5ked","sesionId":"ns5ahsj2ahj","respuesta":"Lo natural es satisfacer la necesidad de los novios en poder ayudarles a tener una gran recuerdo en el día de su boda tanto en foto y video. Lo forzado que he observado y experimentado por el feedback de los propios clientes es que de manera indirecta Douglas a veces les ofrecer en que él será el fotógrafo de la boda a veces muchas novias o novios piensan que él será su fotógrafo, lo digo porque varios novios me han dicho eso en la fase de postventa. Y eso como siento que por cerrar forzamos que él será el fotógrafo. Y muchas veces enviamos a los demás colaboradores a realizar las coberturas, quizá ello como observación. ","fingerprint":"6afbc1ac"}'::jsonb, '2026-07-08T18:02:07.806Z', '2026-07-09T15:31:21.487Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('82e6e064-8e4b-416f-8aa0-80da657b344c', 'a0000000-0000-0000-0000-000000000001', '4f84d799-95aa-4415-94bc-430b84149941', '{"esTest":false,"deviceId":"n7ux0t29oyr","sesionId":"62me03bj76t","respuesta":"Que hagan toda la estructura de fisiólogo, envíen información visual y audiovisual y luego sean más creativos, ágiles y consecuentes. Vender no es copiar y pegar, vender es mostrar la experiencia y como estás sumergida en ella. Par que corra todo, tendrían que tener esa capacidad de saber que son brazos comerciales y tenemos un objetivo común: sostenibilidad y dejar claro esta, un legado de siempre ser los mejores. ","fingerprint":"6471c53"}'::jsonb, '2026-07-09T04:00:07.336Z', '2026-07-09T04:04:54.195Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('6cfd11fd-ae1a-4f40-8cd3-d468ddcdf4ca', 'a0000000-0000-0000-0000-000000000002', '15934cbc-3a6b-494c-95ef-2592c705399e', '{"esTest":false,"deviceId":"rak1qr8d8u","sesionId":"xqms7i93ae","respuesta":"Escuela tiene varias áreas. \n\nAdministrativo: \n- de los grupos nuevos: \n1) el llenado de autorizaciones de imagen y hoja de permiso de salidas y ficha médica \n2) cuantas inasistencias  hubieron en la semana anterior y porque no vinieron \n3) reporte de cuántos grupos están abiertos y cuantos grupos y de qué módulos están por abrir \n\nVentas:\n1)  cuántos nuevos estudiantes están inscritos en cada grupo nuevo por abrir \n\nContable: \n1) reporte de deudores de estudiantes activos porque no pagaron o cuando se ponen al día \n2) ingresos mensuales y proyección \n\nPedagógico: \n1) si los profesores cumplieron con sus clases y actividades según su programación \n2) si los profesores mandaron su Back que se solicita en sus clases prácticas \n3 ) si los Profesores mandaron las mejores fotos logradas en las clases por los alumnos. Para que se sea subido a redes. \n","fingerprint":"4c8cdace"}'::jsonb, '2026-07-09T19:22:41.373Z', '2026-07-09T23:08:41.457Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('b4d708e4-0ed8-4f30-9d60-7c2a2ee7397d', 'a0000000-0000-0000-0000-000000000004', 'c3df03f2-c330-4f2e-bef3-bd3705c3d521', '{"esTest":false,"deviceId":"u05jrx2zvh","sesionId":"aqtglkpzjn","respuesta":"Con los clientes: en la entrega a destiempo de sus productos.\nEn la agenda cuando se agrega un evento de momento, genera inconvenientes.\nEn la coordinación interna, cuando no se proporciona toda la información necesaria para cada evento, o no es correcta.\nCon el equipo mayormente es por temas de puntualidad para llegar a los eventos.","fingerprint":"922d1dfe"}'::jsonb, '2026-07-09T16:25:46.844Z', '2026-07-09T16:31:16.559Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('3bfb6f89-554f-4087-a041-c135fdcaa5db', 'a0000000-0000-0000-0000-000000000003', '8146a170-1fc7-44b4-9ce4-6388c84fa55d', '{"esTest":false,"deviceId":"7wm29mpg7nm","sesionId":"84wetxupq9","respuesta":"Tendria erros al dar la informacion sobre el costos, fechas o beneficios. ","fingerprint":"a75fefd7"}'::jsonb, '2026-07-09T16:12:19.396Z', '2026-07-09T16:22:32.312Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
