INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('a90ee593-2137-4041-a682-a42cb9276ec3', 'a0000000-0000-0000-0000-000000000003', 'add9edd8-8890-48fe-92aa-3c20b7b7abae', '{"esTest":false,"deviceId":"7wm29mpg7nm","sesionId":"84wetxupq9","respuesta":"Creo que un fallo es el tema del transpaso de los numeros que ingresan ya que en la segunta respuesta el 50% ya no vuelve a responder. \nLa diferencia entre infraestructura y entrega entre la ciudad de trujillo y piura","fingerprint":"a75fefd7"}'::jsonb, '2026-07-09T16:18:27.052Z', '2026-07-09T16:22:32.312Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
