INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('3cc7f775-930e-4403-8793-60e3ca1d78b9', 'a0000000-0000-0000-0000-000000000006', '13ccef88-63f2-43ce-abf0-09bed40678fe', '{"esTest":false,"deviceId":"edbd5udh1s6","sesionId":"ddhwzkywf64","respuesta":"Se usan, plantillas para coberturas de colegios (RECAP SESIONES COLEGIOS) o para fotos sueltas de escuela (BACK). ","fingerprint":"e085e45"}'::jsonb, '2026-07-09T15:08:35.206Z', '2026-07-09T15:54:13.393Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
INSERT INTO respuesta (id, asignacion_id, pregunta_id, valor, creado_en, actualizado_en) VALUES ('5897c278-7226-41d1-9da8-b83ae204dbf9', 'a0000000-0000-0000-0000-000000000002', '9cb19385-8bd4-47f6-9488-25e0c3d84ec4', '{"esTest":false,"deviceId":"rak1qr8d8u","sesionId":"xqms7i93ae","respuesta":"ACTORES:\n1)\tCOLABORADORES OPERATIVOS ( fotógrafos, video, diseñadores, etc) :\n-\tTardanzas, permisos, monitoreo registro y compensación de tiempos extras, tener al día sus contratos, renovaciones, etc (necesitamos RRHH) \n-\tPerdidas, equipos malogrados de equipo utilizado de productora. \n-\tUso indebido del material que recogen en la empresa. (derechos de imagen, regulado en hoja de compromiso al inicio de su ingreso)\n\n2)\tCLIENTES:\n-\tProblema 1: no están a gusto por la entrega del producto final ( no se les dio una explicación a detalle del contrato en un inicio, o hubieron muchos cambios modificados en el proceso que se perdió la comunicación entre coordinadores y operativos para que ejecuten según la especificación.\n-\tProblema 2: Aunque todo este bien el cliente simplemente no le gusta lo que se le entrega (Quizas fortalecer cláusulas de los contratos o mas rigidez en las coordinaciones durante el proceso)\n-\tProblema 3: Una vez  coordinados los servicios y entregables, los clientes quieren cortesías y cosas a su favor como modificaciones en rostro, etc. Sin pagar mas ( Coordinador debe tener mayor rigidez en no aceptar). \n3)\tPROVEEDORES: \n-\tA veces no entregan lo que ofrecen en tiempo o forma y algunas veces se les paga justo antes de que comience su servicio. Y no quieren devolver dinero. O el proveedor no existe y se le deposito, en el caso de atención a otras ciudades donde tercerizamos y es difícil ir a monitorear.\n4)\tPROCESOS:\na)\tReclutamiento:\n-\tLos nuevos postulantes pueden tener una falsa expectativa de lo que se va a hacer. ( en la inducción se habla mucho pero no hay cosas puntuales, habría que tener un formato escrito según puesto) \n-\tMuchos nuevos postulantes no aguantan o se retiran en menos de una semana de haber entrado.\n-\tTener claro si vamos a pagar o no las inducciones ( porque algunos quieren q se paguen las inducciones cuando solo las recibieron y en esa misma semana desertaron. (  en gerencia lo vemos como una pérdida de tiempo en vez de una inversión de tiempo que podría ser remunerada) \nb)\tCultura organizacional:\n-\tNo contamos con una misión, visión y valores de la empresa  redactada, debemos colocarla a la vista para que todos puedan tenerla presente siempre. \nc)\tVentas – Post venta:\n-\tNo hay suficiente captación de clientes nuevos en agencia y en escuela\n-\tActualmente solo Douglas sostiene las ventas y es mucho tiempo el que le lleva mas tiempo del horario laboral usa  sus  16 horas para vender. \nd)\tCoordinaciones:\n-\tJenny: es buena en administrativo y documentación sin embargo no tiene una coordinación operativa con liderazgo: genera problemas con los operativos que no quieren ir a las comisiones que se les indican, los operativos no siempre saben las actividades que tienen que ejecutar ni en tiempo ni en forma y hay problemas en la entrega al cliente final. No comunica rápidamente alguna coordinación y genera contratiempos entre cliente, proveedor, etc.\n-\tJosef:  no es tan eficiente en administrativo, pero  al ser pro activo puede dar seguimiento con mayor agilidad a los clientes y resolver problemas con clientes especiales, llegando a mejores acuerdos. Al comunicar  con mayor fluidez a gerencia cualquier problema evita que estos se hagan mas grandes.  Pero  es muy confiado asique cuando se le asigna algún proyecto como los de UTP, muchas veces deja todo a ultimo  y los proveedores le quedan mal lo que genera problemas. \ne)\tEstandarizar devolución de viáticos por comisiones.\n-\tSe producen malestares por que  muchas veces el monto por viáticos que se egresa a algún personal no son iguales a otros, pues se termina valorando muchos factores como  horarios, lugares, feriados, etc Esto genera mucha controversia con los operativos. \nd) Reportes contables de escuela: \n- En productora tenemos mas orden pero en escuela  hay mucho problema con saber la recaudación exacta, pues la persona que actualmente esta no logra dar un reporte claro, se confunde mucho con los números  de ingreso, ya que los ingresos de dinero en escuela son muy variables, según la fecha de ingreso y cierre de curso  o si hay bajas o retrasos pro los alumnos.. así que no se logra estandarizar una tabla que mida exactamente la proyección de dinero en el futuro. ( se esta pensando contratar un contador para ver ello) \n","fingerprint":"4c8cdace"}'::jsonb, '2026-07-09T20:24:25.655Z', '2026-07-09T23:08:41.457Z') ON CONFLICT (id) DO UPDATE SET valor = EXCLUDED.valor, actualizado_en = EXCLUDED.actualizado_en;
